{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table rashu_db.maplemonk.flipkart_order_fulfilment_fact_items as select replace(replace(sku, \'\"\', \'\'), \'sku:\', \'\') as sku, order_id as reference_code, order_id, replace(order_item_id,\'OI:\',\'\') ordeR_item_id, replace(product_title, \'\"\', \'\') as product_name, to_timestamp(order_date) as order_date, to_timestamp(nullif(replace(order_approval_date, \'\"\', \'\'), \'\')) as order_approval_date, to_timestamp(nullif(order_cancellation_date, \'\')) as cancellation_date, to_timestamp(nullif(dispatch_after_date, \'\')) as manifest_date, to_timestamp(nullif(dispatch_by_date, \'\')) as dispatch_date, case when deliver_by_date = \'N\' then null else cast(deliver_by_date as date) end as delivery_date, to_timestamp(nullif(order_return_approval_date, \'\')) as return_approval_date, case when upper(pickup_logistics_partner) like \'%cod%\' then \'cod\' else \'prepaid\' end as payment_mode, fulfilment_type, fulfilment_source, order_item_status, cancellation_reason, replace(delivery_tracking_id, \'dtr:\', \'\') as fk_awb from maplemonk.rashu_toys_fk_orders qualify row_number() over (partition by order_id,order_item_id order by return_approval_date desc) = 1 ; create or replace table rashu_db.maplemonk.rashu_toys_flipkart_fact_items as select case when s.\"Fulfilment Type\" = \'NON_FBF\' then \'Flipkart Rashu Toys\' else \'Flipkart FBF Rashu Toys\' end as shop_name, cast(s.\"Order ID\" as string) as order_id, cast(s.\"Order ID\" as string) as order_name, NULL as customer_id, NULL as phone, cast(NULL as string) as tags, cast(s.\"Order Item ID\" as string) as line_item_id, cast(replace(replace(s.sku,\'\"\',\'\'),\'SKU:\',\'\') as string) as SKU, replace(s.FSN,\'\"\',\'\') as product_id, case when s.\"Event Type\" = \'Return\' then 1 else 0 end as is_refund, cast(NULL as string) as city, case when s.\"Customer\'s Delivery State\" = \'-\' then (case when s.\"Customer\'s Billing State\" = \'-\' then null else s.\"Customer\'s Billing State\" end) else s.\"Customer\'s Delivery State\" end as state, case when s.\"Customer\'s Delivery Pincode\" = \'-\' then (case when s.\"Customer\'s Billing Pincode\" = \'-\' then null else s.\"Customer\'s Billing Pincode\"::int end) else s.\"Customer\'s Delivery Pincode\"::int end as pincode, replace(\"Product Title/Description\",\'\"\',\'\') as PRODUCT_NAME, cast(Null as string) as category, f.order_date, f.order_item_status, f.fulfilment_type, f.fulfilment_source, f.cancellation_reason, f.payment_mode, abs(ifnull(cast(\"Price after discount (Price before discount-Total discount)\" as float),0)) as line_item_sales, abs(ifnull(cast(\"Shipping Charges\" as float),0) )as shipping_price, abs(ifnull(cast(\"Item Quantity\" as float),0)) as quantity, abs(ifnull(cast(\"Total TCS Deducted\" as float),0)) as tax, abs(div0(ifnull(cast(\"Price after discount (Price before discount-Total discount)\" as float),0),(ifnull(cast(\"Price after discount (Price before discount-Total discount)\" as float),0)+ifnull(cast(\"Total TCS Deducted\" as float),0)))) as overall_tax_rate, abs(ifnull(cast(\"Total Discount\" as float),0)) as discount, div0(discount,(1-div0(tax,(tax+line_item_sales)))) as discount_before_tax, (line_item_sales - discount_before_tax) as gross_sales_before_tax, abs(ifnull(cast(\"Price after discount (Price before discount-Total discount)\" as float),0)) as total_sales, case when \"Is Shopsy Order?\" = TRUE then \'Shopsy Order\' else \'Flipkart Order\' end as Order_Channel, \"Beneficiary Name\" as name, cast(null as string) as email from ( select * from maplemonk.rashu_toys_sales qualify row_number() over (partition by \"Order Item ID\",\"Order ID\" order by \"Buyer Invoice Date\" desc) = 1 ) s left join maplemonk.flipkart_order_fulfilment_fact_items f on f.order_id = s.\"Order ID\" and f.order_item_id = s.\"Order Item ID\"; CREATE OR REPLACE TABLE rashu_db.maplemonk.flipkart_sales_cost_source AS WITH ads_data AS ( SELECT date, Total_Converted_units AS units_sold, Total_Revenue AS revenue, spend, Clicks, views FROM rashu_db.maplemonk.flipkart_seller_pla_fact_items ), sales_data AS ( SELECT order_date, SUM(total_sales) AS total_sales, SUM(quantity) AS quantity FROM rashu_db.maplemonk.rashu_toys_flipkart_fact_items ) SELECT COALESCE(s.order_date, a.date) AS order_date, total_sales, quantity, units_sold, revenue, spend, clicks, views FROM sales_data s FULL OUTER JOIN ads_data a ON s.order_date = a.date ; create or replace table emmasleep_db.maplemonk.flipkart_sales_cost_source as with ads_data as ( select date, sum(direct_units) ad_units, sum(direct_revenue) ad_revenue, sum(spend) spend, sum(clicks) clicks, sum(views) views from emmasleep_db.maplemonk.flipkart_fact_items group by 1 ) , sales_data as ( select ordeR_Date, sum(selling_price) total_Sales, sum(b.cost*quantity) total_cost, sum(quantity) quantity from EMMASLEEP_DB.MAPLEMONK.EMMASLEEP_DB_sales_consolidated a left join (select sku, cost from (select sku, bettersleep::float cost, row_number() over (partition by sku order by 1) rw from rashu_db.maplemonk.mapping_sku_cogs) where rw = 1)b on a.sku = b.sku where marketplace = \'FLIPKART\' group by 1 ) select coalesce(order_date, date) order_date, total_sales, quantity, ad_units, ad_revenue, spend, clicks, views from sales_Data s left join ads_data a on s.order_Date = a.date ;",
                    "transaction": true
                }
            ) }}
